import { useEffect, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import { useDesk } from "@/lib/useDesk";
import { useTheme } from "@/contexts/ThemeContext";
import { Activity, ArrowUpRight, BarChart3, Bell, CircleDashed, Clock3, Database, FileText, Filter, Instagram, Mail, Menu, Moon, MoreHorizontal, Package, Search, Send, ShieldCheck, Sparkles, Sprout, Sun, Target, UserRound, Wallet, Wifi, X } from "lucide-react";

type CreatorView = {
  creatorId: string;
  name: string;
  handle: string;
  profileUrl: string;
  industry: string;
  subNiche: string | null;
  stage: string;
  researchStatus: string;
  confidence: string;
  qualificationScore: number;
  approvalStatus: string;
};

type EvidenceView = { id: number; evidenceType: string; title: string; sourceUrl: string | null; summary: string; signal: string; confidence: string; capturedAt: string };
type ScreeningView = { audienceFit: number; buyingSignals: number; expertiseAuthority: number; partnershipReadiness: number; decision: string; rationale: string | null };
type DraftView = { id: number; creatorId: string; channel: string; subject: string | null; body: string; personalizationSummary: string | null; status: string; approvedAt: string | null; sentAt: string | null; createdAt: string; updatedAt: string };
type FollowupView = { id: number; creatorId: string; draftId: number | null; channel: string; dueAt: string; status: string; note: string | null; createdAt: string };
type ProductBriefView = { id: number; creatorId: string; hypothesisNumber: number; productName: string; audienceProblem: string; buyingSignal: string | null; transformation: string; format: string; outline: string; assetRequirements: string | null; visualDirection: string | null; launchNotes: string | null; status: string; productionReport: string | null; reviewNotes: string | null; reviewedAt: string | null; approvedAt: string | null; createdAt: string; updatedAt: string };
type MarketingPlanView = { id: number; creatorId: string; productBriefId: number | null; campaignName: string; audienceSegment: string; positioning: string; offerAngle: string; voiceNotes: string | null; preLaunchStrategy: string; postLaunchStrategy: string; assetChecklist: string | null; status: string; reviewedAt: string | null; approvedAt: string | null; createdAt: string; updatedAt: string };
type MarketingItemView = { id: number; creatorId: string; planId: number | null; productBriefId: number | null; phase: string; channel: string; contentType: string; title: string; objective: string; hook: string | null; body: string | null; callToAction: string | null; assetDirection: string | null; scheduledFor: string | null; status: string; createdAt: string; updatedAt: string };
type RevenueProductView = { id: number; creatorId: string; productBriefId: number | null; whopProductId: string | null; productName: string; status: string; currency: string; lastSyncedAt: string | null; createdAt: string; updatedAt: string };
type RevenueTermView = { id: number; creatorId: string; whopProductId: number; creatorSharePercent: number; shadowSharePercent: number; negotiated: boolean; effectiveAt: string; status: string; createdAt: string; updatedAt: string };
type RevenueTransactionView = { id: number; whopPaymentId: string | null; creatorId: string; whopProductId: number | null; grossAmountCents: number; whopFeesCents: number; refundsCents: number; netAmountCents: number; creatorShareCents: number; shadowShareCents: number; currency: string; paymentStatus: string; paidAt: string | null; source: string; importedAt: string };

const priorityCreators: CreatorView[] = [
  ["Ornagarden Kick", "onagardenkick"], ["Quarter Acre Roots", "quarteracreroots"], ["Michelle", "everydaygardeningtips"], ["Tyler & Brian", "gardenerinlove"], ["Alison", "cookseyfarms"], ["Inna", "gardens_better_with_cats"], ["Timothy Hammond", "bigcitygardener"], ["Milan Turner", "atlgrow"], ["Meenakshi", "meditativegardening"], ["Helier", "garden_goddess_uk"], ["Jo Thompson", "jothompsongarden"], ["Katie Townsend", "katietownsendgardendesign"], ["Joanna Archer Garden Design", "joannaarchergardendesign"], ["Kamili Bell Hill", "plantblerd"], ["Kaylee Ellen", "kayleeellenofficial"], ["Ashley Anita", "lifewithashleyanita"], ["Amy", "thehobbyhomestead"], ["Gardening Indoors", "_gardeningindoors"], ["Gardenerd", "gardenerd1"], ["Cloud Gardener", "cloudgardeneruk"], ["Kath Irvine", "edible.backyard"], ["Carly", "thegardenspot"], ["Tony", "tonygrowsfood"], ["Beth", "filipinafarmstead"], ["Dominika", "17m2garden"], ["Divya Kanwar", "indiangreendreams"], ["Kia Jade", "kia_urbangardener"], ["Peter Vouthas", "urbancitygardener"], ["Jill Mc Sheehy", "thebeginnersgarden"], ["Adam Long", "itsanadamadventure"], ["Front Porch", "frontporchfarmer"],
].map(([name, handle], index) => ({ creatorId: `SO-${String(index + 1).padStart(4, "0")}`, name, handle, profileUrl: `https://www.instagram.com/${handle}/`, industry: "Gardening", subNiche: index % 3 === 0 ? "Urban food growing" : index % 3 === 1 ? "Homesteading & edible gardens" : "Garden design & education", stage: "discovery", researchStatus: "unverified", confidence: "unknown", qualificationScore: 0, approvalStatus: "not_ready" }));

const stageMeta: Record<string, { label: string; tone: string }> = {
  discovery: { label: "Discovery", tone: "" },
  screening: { label: "Screening", tone: "" },
  qualified: { label: "Qualified", tone: "" },
  outreach: { label: "Outreach", tone: "attention" },
  replied: { label: "Replied", tone: "" },
  partnership: { label: "Partnership", tone: "" },
  product: { label: "Product", tone: "attention" },
  launch: { label: "Launch", tone: "" },
  live: { label: "Live", tone: "" },
  archived: { label: "Archived", tone: "" },
};

function normalizeCreator(record: any): CreatorView {
  return { creatorId: record.creatorId ?? record.creator_id, name: record.name, handle: record.handle, profileUrl: record.profileUrl ?? record.profile_url, industry: record.industry, subNiche: record.subNiche ?? record.sub_niche ?? null, stage: record.stage, researchStatus: record.researchStatus ?? record.research_status, confidence: record.confidence, qualificationScore: record.qualificationScore ?? record.qualification_score ?? 0, approvalStatus: record.approvalStatus ?? record.approval_status };
}

function Metric({ icon: Icon, label, value, detail }: { icon: typeof Activity; label: string; value: string; detail: string; tone?: "amber" | "sage" | "ink" }) {
  return <div className="metric-card"><Icon size={16} className="metric-icon" aria-hidden="true" /><p className="metric-label">{label}</p><p className="metric-value">{value}</p><p className="metric-detail">{detail}</p></div>;
}

function statusLabel(record: CreatorView) {
  if (record.researchStatus === "audit_complete") return "Audit complete";
  if (record.researchStatus === "deep_research") return "Deep research";
  if (record.researchStatus === "profile_verified") return "Profile verified";
  return "Profile unverified";
}

type ViewKey = "overview" | "creators" | "approvals" | "outreach" | "products" | "marketing" | "revenue" | "reports";

type WorkspaceViewProps = {
  view: Exclude<ViewKey, "overview">;
  records: CreatorView[];
  counts: Record<string, number>;
  liveLabel: string;
  onOpenCreator: (creatorId: string) => void;
  drafts: DraftView[];
  followups: FollowupView[];
  onDraftStatus: (id: number, status: "needs_review" | "approved" | "sent" | "replied" | "rejected" | "archived") => void;
  onCreateDraft: (input: { creatorId: string; channel: "instagram" | "email"; subject: string | null; body: string; personalizationSummary: string | null }) => void;
  onScheduleFollowup: (input: { creatorId: string; draftId: number | null; channel: "instagram" | "email"; dueAt: string; note: string | null }) => void;
  productBriefs: ProductBriefView[];
  onCreateProductBrief: (input: { creatorId: string; hypothesisNumber: number; productName: string; audienceProblem: string; buyingSignal: string | null; transformation: string; format: string; outline: string; assetRequirements: string | null; visualDirection: string | null; launchNotes: string | null }) => void;
  onUpdateProductBrief: (input: { id: number; status?: "architected" | "handed_off" | "in_production" | "submitted_for_review" | "revision_requested" | "approved" | "archived"; productionReport?: string | null; reviewNotes?: string | null }) => void;
  marketingPlans: MarketingPlanView[];
  marketingItems: MarketingItemView[];
  onCreateMarketingPlan: (input: { creatorId: string; productBriefId: number | null; campaignName: string; audienceSegment: string; positioning: string; offerAngle: string; voiceNotes: string | null; preLaunchStrategy: string; postLaunchStrategy: string; assetChecklist: string | null }) => void;
  onUpdateMarketingPlan: (input: { id: number; status: "needs_review" | "approved" | "active" | "paused" | "archived" }) => void;
  onCreateMarketingItem: (input: { creatorId: string; planId: number | null; productBriefId: number | null; phase: "pre_launch" | "launch" | "post_launch"; channel: "instagram" | "email" | "whop" | "community" | "other"; contentType: string; title: string; objective: string; hook: string | null; body: string | null; callToAction: string | null; assetDirection: string | null; scheduledFor: string | null }) => void;
  onUpdateMarketingItem: (input: { id: number; status: "needs_review" | "approved" | "ready" | "published" | "archived" }) => void;
  revenueProducts: RevenueProductView[];
  revenueTerms: RevenueTermView[];
  revenueTransactions: RevenueTransactionView[];
};

function ProductBriefRow({ brief, records, onUpdate }: { brief: ProductBriefView; records: CreatorView[]; onUpdate: WorkspaceViewProps["onUpdateProductBrief"] }) {
  const [report, setReport] = useState(brief.productionReport ?? "");
  const [review, setReview] = useState(brief.reviewNotes ?? "");
  const creatorName = records.find(record => record.creatorId === brief.creatorId)?.name ?? brief.creatorId;
  const canSubmit = report.trim().length >= 20;
  return <div className="product-brief-row"><div className="product-brief-top"><div><span className="eyebrow">Direction {brief.hypothesisNumber} · {creatorName}</span><h3>{brief.productName}</h3><p>{brief.format} · {brief.status.replaceAll("_", " ")}</p></div><Badge variant="outline">{brief.status.replaceAll("_", " ")}</Badge></div><div className="product-brief-grid"><div><strong>Audience problem</strong><p>{brief.audienceProblem}</p></div><div><strong>Transformation</strong><p>{brief.transformation}</p></div><div><strong>Architecture</strong><p>{brief.outline}</p></div><div><strong>Visual direction</strong><p>{brief.visualDirection || "Not specified yet"}</p></div></div><div className="product-row-actions">{brief.status === "hypothesis" && <Button size="sm" variant="outline" onClick={() => onUpdate({ id: brief.id, status: "architected" })}>Mark architected</Button>}{brief.status === "architected" && <Button size="sm" variant="outline" onClick={() => onUpdate({ id: brief.id, status: "handed_off" })}>Hand off to production</Button>}{brief.status === "handed_off" && <Button size="sm" variant="outline" onClick={() => onUpdate({ id: brief.id, status: "in_production" })}>Mark in production</Button>}{["in_production", "revision_requested"].includes(brief.status) && <div className="review-inputs"><textarea aria-label="Production report" value={report} onChange={event => setReport(event.target.value)} placeholder="Paste the Higgsfield + Claude production report here…"/><Button size="sm" className="primary-button" disabled={!canSubmit} onClick={() => onUpdate({ id: brief.id, status: "submitted_for_review", productionReport: report.trim() })}>Submit production report</Button></div>}{brief.status === "submitted_for_review" && <div className="review-inputs"><textarea aria-label="Review notes" value={review} onChange={event => setReview(event.target.value)} placeholder="ShadowOS review notes: gaps, corrections, approval conditions…"/><div className="review-buttons"><Button size="sm" variant="outline" onClick={() => onUpdate({ id: brief.id, status: "revision_requested", reviewNotes: review.trim() || "Revision required before approval." })}>Request revision</Button><Button size="sm" className="primary-button" disabled={!review.trim()} onClick={() => onUpdate({ id: brief.id, status: "approved", reviewNotes: review.trim() })}>Approve product</Button></div></div>}{brief.status === "approved" && <span className="approved-note"><ShieldCheck size={14}/> Approved after production report review</span>}</div></div>;
}

function WorkspaceView({ view, records, counts, liveLabel, onOpenCreator, drafts, followups, onDraftStatus, onCreateDraft, onScheduleFollowup, productBriefs, onCreateProductBrief, onUpdateProductBrief, marketingPlans, marketingItems, onCreateMarketingPlan, onUpdateMarketingPlan, onCreateMarketingItem, onUpdateMarketingItem, revenueProducts, revenueTerms, revenueTransactions }: WorkspaceViewProps) {
  const qualified = records.filter(record => ["qualified", "outreach", "replied", "partnership", "product", "launch", "live"].includes(record.stage));
  const needsApproval = records.filter(record => record.approvalStatus === "needs_review");
  const [showDraftForm, setShowDraftForm] = useState(false);
  const [draftCreatorId, setDraftCreatorId] = useState(qualified[0]?.creatorId ?? "");
  const [draftChannel, setDraftChannel] = useState<"instagram" | "email">("instagram");
  const [draftSubject, setDraftSubject] = useState("");
  const [draftBody, setDraftBody] = useState("");
  const [draftPersonalization, setDraftPersonalization] = useState("");
  const submitDraft = () => { if (!draftCreatorId || draftBody.trim().length < 20) return; onCreateDraft({ creatorId: draftCreatorId, channel: draftChannel, subject: draftSubject.trim() || null, body: draftBody.trim(), personalizationSummary: draftPersonalization.trim() || null }); setDraftBody(""); setDraftSubject(""); setDraftPersonalization(""); setShowDraftForm(false); };
  const [showFollowupForm, setShowFollowupForm] = useState(false);
  const [followupDraftId, setFollowupDraftId] = useState<number | null>(drafts[0]?.id ?? null);
  const [followupDueAt, setFollowupDueAt] = useState("");
  const [followupNote, setFollowupNote] = useState("");
  const submitFollowup = () => { const draft = drafts.find(item => item.id === followupDraftId); if (!draft || !followupDueAt) return; onScheduleFollowup({ creatorId: draft.creatorId, draftId: draft.id, channel: draft.channel as "instagram" | "email", dueAt: new Date(followupDueAt).toISOString(), note: followupNote.trim() || null }); setFollowupNote(""); setFollowupDueAt(""); setShowFollowupForm(false); };
  const [showProductForm, setShowProductForm] = useState(false);
  const [productForm, setProductForm] = useState({ creatorId: qualified[0]?.creatorId ?? "", hypothesisNumber: 1, productName: "", audienceProblem: "", buyingSignal: "", transformation: "", format: "", outline: "", assetRequirements: "", visualDirection: "", launchNotes: "" });
  const submitProduct = () => { if (!productForm.creatorId || productForm.productName.trim().length < 2 || productForm.audienceProblem.trim().length < 10 || productForm.transformation.trim().length < 10 || productForm.outline.trim().length < 20) return; onCreateProductBrief({ ...productForm, productName: productForm.productName.trim(), audienceProblem: productForm.audienceProblem.trim(), buyingSignal: productForm.buyingSignal.trim() || null, transformation: productForm.transformation.trim(), format: productForm.format.trim() || "Digital guide", outline: productForm.outline.trim(), assetRequirements: productForm.assetRequirements.trim() || null, visualDirection: productForm.visualDirection.trim() || null, launchNotes: productForm.launchNotes.trim() || null }); setShowProductForm(false); };
  const [showMarketingForm, setShowMarketingForm] = useState(false);
  const [marketingForm, setMarketingForm] = useState({ creatorId: qualified[0]?.creatorId ?? "", productBriefId: null as number | null, campaignName: "", audienceSegment: "", positioning: "", offerAngle: "", voiceNotes: "", preLaunchStrategy: "", postLaunchStrategy: "", assetChecklist: "" });
  const submitMarketingPlan = () => { if (!marketingForm.creatorId || marketingForm.campaignName.trim().length < 2 || marketingForm.audienceSegment.trim().length < 10 || marketingForm.positioning.trim().length < 10 || marketingForm.offerAngle.trim().length < 10 || marketingForm.preLaunchStrategy.trim().length < 20 || marketingForm.postLaunchStrategy.trim().length < 20) return; onCreateMarketingPlan({ ...marketingForm, campaignName: marketingForm.campaignName.trim(), audienceSegment: marketingForm.audienceSegment.trim(), positioning: marketingForm.positioning.trim(), offerAngle: marketingForm.offerAngle.trim(), voiceNotes: marketingForm.voiceNotes.trim() || null, preLaunchStrategy: marketingForm.preLaunchStrategy.trim(), postLaunchStrategy: marketingForm.postLaunchStrategy.trim(), assetChecklist: marketingForm.assetChecklist.trim() || null }); setShowMarketingForm(false); };
  const title = { creators: "Creators", approvals: "Approvals", outreach: "Outreach", products: "Products", marketing: "Marketing", revenue: "Whop revenue", reports: "Reports" }[view];
  const description = {
    creators: "Every creator record, stage, and next action in one workspace.",
    approvals: "Human decisions before any external message or partnership action.",
    outreach: "Channel-ready drafts, send history, and follow-up control.",
    products: "Creator-specific product hypotheses and build stages.",
    marketing: "Creator-specific pre-launch, launch, and post-launch campaigns.",
    revenue: "Whop attribution and revenue-share visibility by creator and product.",
    reports: "A concise operating view of pipeline health and blockers.",
  }[view];
  return <div className="content-wrap">
    <div className="section-heading view-heading"><div><p className="eyebrow amber-text">ShadowOS workspace</p><h2>{title}</h2><p className="section-desc">{description}</p></div><div className="heading-actions"><Badge className="view-source"><Wifi size={12}/> {liveLabel}</Badge><Button className="primary-button" onClick={() => view === "outreach" ? setShowDraftForm(value => !value) : records[0] && onOpenCreator(records[0].creatorId)}><Sparkles size={15}/> {view === "outreach" ? (showDraftForm ? "Close draft form" : "New draft") : view === "products" ? "Open product workspace" : "Open queue"}</Button></div></div>
    {view === "creators" && <><div className="metrics-grid compact-metrics"><Metric icon={UserRound} label="All creators" value={String(records.length)} detail="in the live workspace"/><Metric icon={CircleDashed} label="Discovery" value={String(counts.discovery ?? 0)} detail="not yet screened" tone="sage"/><Metric icon={Target} label="Qualified" value={String(qualified.length)} detail="ready for a decision"/></div><Card className="workspace-panel"><CardHeader><CardTitle>Creator directory</CardTitle><p className="table-subtitle">Select a record to return to its evidence workspace.</p></CardHeader><CardContent className="directory-grid">{records.map(record => <button className="directory-card" key={record.creatorId} onClick={() => onOpenCreator(record.creatorId)}><div className="directory-avatar">{record.name.split(" ").map(x => x[0]).join("").slice(0,2)}</div><div><strong>{record.name}</strong><span>@{record.handle}</span><small>{record.creatorId} · {record.subNiche ?? "Niche not set"}</small></div><ArrowUpRight size={15}/></button>)}</CardContent></Card></>}
    {view === "approvals" && <Card className="workspace-panel"><CardHeader><CardTitle>Approval queue <span className="count-pill">{needsApproval.length}</span></CardTitle><p className="table-subtitle">Nothing is sent or published without an explicit approval state.</p></CardHeader><CardContent>{needsApproval.length ? needsApproval.map(record => <div className="queue-row" key={record.creatorId}><div><strong>{record.name}</strong><span>{record.creatorId} · qualification review</span></div><Badge variant="outline">Needs review</Badge></div>) : <div className="empty-state"><div className="empty-icon"><ShieldCheck size={22}/></div><h3>Approval queue is clear</h3><p>Screen a creator first. Qualified records will appear here before outreach or publishing.</p><Button variant="outline" onClick={() => records[0] && onOpenCreator(records[0].creatorId)}>Go to creator queue</Button></div>}</CardContent></Card>}
    {view === "outreach" && <><div className="metrics-grid compact-metrics"><Metric icon={Send} label="Drafts" value={String(drafts.length)} detail="saved in ShadowOS"/><Metric icon={Instagram} label="Instagram" value={String(drafts.filter(draft => draft.channel === "instagram").length)} detail="manual send only" tone="sage"/><Metric icon={Mail} label="Email" value={String(drafts.filter(draft => draft.channel === "email").length)} detail="approval-gated"/></div>{showDraftForm && <Card className="workspace-panel draft-composer"><CardHeader><CardTitle>New creator-specific draft</CardTitle><p className="table-subtitle">Saving a draft never sends a message. Only qualified creators are selectable.</p></CardHeader><CardContent><div className="composer-grid"><label>Creator<select value={draftCreatorId} onChange={event => setDraftCreatorId(event.target.value)}>{qualified.length ? qualified.map(record => <option key={record.creatorId} value={record.creatorId}>{record.name} · {record.creatorId}</option>) : <option value="">No qualified creators</option>}</select></label><label>Channel<select value={draftChannel} onChange={event => setDraftChannel(event.target.value as typeof draftChannel)}><option value="instagram">Instagram DM · manual send</option><option value="email">Email</option></select></label><label>Subject <span className="field-hint">email only</span><input value={draftSubject} onChange={event => setDraftSubject(event.target.value)} placeholder="A concise subject"/></label><label>Personalization summary<input value={draftPersonalization} onChange={event => setDraftPersonalization(event.target.value)} placeholder="Evidence this draft uses"/></label><label className="wide-field">Message body<textarea value={draftBody} onChange={event => setDraftBody(event.target.value)} placeholder="Write the creator-specific message…"/></label></div><div className="form-actions"><Button variant="outline" onClick={() => setShowDraftForm(false)}>Cancel</Button><Button className="primary-button" onClick={submitDraft} disabled={!qualified.length || draftBody.trim().length < 20}>Save draft</Button></div></CardContent></Card>}<Card className="workspace-panel"><CardHeader><CardTitle>Outreach control</CardTitle><p className="table-subtitle">Drafts, approvals, send logs, replies, and follow-ups stay linked to a creator.</p></CardHeader><CardContent>{drafts.length ? <div className="draft-list">{drafts.map(draft => <div className="draft-row" key={draft.id}><div className={cn("channel-symbol", draft.channel === "instagram" ? "instagram" : "email")} >{draft.channel === "instagram" ? <Instagram size={17}/> : <Mail size={17}/>}</div><div className="draft-main"><strong>{records.find(record => record.creatorId === draft.creatorId)?.name ?? draft.creatorId}</strong><span>{draft.subject || "Instagram direct message"}</span><small>{draft.body.slice(0, 120)}{draft.body.length > 120 ? "…" : ""}</small></div><div className="draft-actions"><Badge variant="outline">{draft.status.replace("_", " ")}</Badge>{draft.status === "draft" && <Button size="sm" variant="outline" onClick={() => onDraftStatus(draft.id, "needs_review")}>Submit review</Button>}{draft.status === "needs_review" && <Button size="sm" className="primary-button" onClick={() => onDraftStatus(draft.id, "approved")}>Approve</Button>}{draft.status === "approved" && <Button size="sm" variant="outline" onClick={() => onDraftStatus(draft.id, "sent")}>Mark sent</Button>}</div></div>)}</div> : <div className="empty-state small-empty"><div className="empty-icon"><Send size={20}/></div><h3>No outreach drafts yet</h3><p>Only qualified creators can enter the draft queue. Drafting never sends a message.</p></div>}{showFollowupForm && <div className="inline-form followup-form"><label>Draft<select value={followupDraftId ?? ""} onChange={event => setFollowupDraftId(Number(event.target.value))}>{drafts.map(draft => <option key={draft.id} value={draft.id}>{draft.id} · {records.find(record => record.creatorId === draft.creatorId)?.name ?? draft.creatorId}</option>)}</select></label><label>Due date and time<input type="datetime-local" value={followupDueAt} onChange={event => setFollowupDueAt(event.target.value)}/></label><textarea aria-label="Follow-up note" placeholder="Follow-up note" value={followupNote} onChange={event => setFollowupNote(event.target.value)}/><div className="form-actions"><Button variant="outline" size="sm" onClick={() => setShowFollowupForm(false)}>Cancel</Button><Button size="sm" className="primary-button" onClick={submitFollowup} disabled={!drafts.length || !followupDueAt}>Schedule follow-up</Button></div></div>}<div className="followup-strip"><strong>Follow-up queue</strong><span>{followups.length ? `${followups.length} scheduled follow-up${followups.length === 1 ? "" : "s"}` : "No follow-ups scheduled"}</span><Button size="sm" variant="outline" onClick={() => setShowFollowupForm(value => !value)}>{showFollowupForm ? "Close" : "Schedule"}</Button></div></CardContent></Card></>}
    {view === "products" && <><div className="metrics-grid compact-metrics"><Metric icon={Package} label="Briefs" value={String(productBriefs.length)} detail="creator-specific"/><Metric icon={FileText} label="In production" value={String(productBriefs.filter(brief => ["handed_off","in_production"].includes(brief.status)).length)} detail="Higgsfield + Claude handoff" tone="sage"/><Metric icon={ShieldCheck} label="Review queue" value={String(productBriefs.filter(brief => brief.status === "submitted_for_review").length)} detail="awaiting ShadowOS review"/></div><div className="product-toolbar"><div><p className="eyebrow amber-text">Architecture before manufacturing</p><p className="product-guidance">ShadowOS prepares the product blueprint. Higgsfield and Claude manufacture the digital product. You paste the production report here for review.</p></div><Button className="primary-button" onClick={() => setShowProductForm(value => !value)}><Package size={15}/> {showProductForm ? "Close brief form" : "New product brief"}</Button></div>{showProductForm && <Card className="workspace-panel product-composer"><CardHeader><CardTitle>Create product architecture brief</CardTitle><p className="table-subtitle">Only qualified creators can receive a product brief. Choose one of four hypothesis slots.</p></CardHeader><CardContent><div className="composer-grid"><label>Creator<select value={productForm.creatorId} onChange={event => setProductForm(current => ({ ...current, creatorId: event.target.value }))}>{qualified.length ? qualified.map(record => <option key={record.creatorId} value={record.creatorId}>{record.name} · {record.creatorId}</option>) : <option value="">No qualified creators</option>}</select></label><label>Hypothesis slot<select value={productForm.hypothesisNumber} onChange={event => setProductForm(current => ({ ...current, hypothesisNumber: Number(event.target.value) }))}>{[1,2,3,4].map(slot => <option key={slot} value={slot}>Direction {slot}</option>)}</select></label><label>Product name<input value={productForm.productName} onChange={event => setProductForm(current => ({ ...current, productName: event.target.value }))} placeholder="Working product name"/></label><label>Format<input value={productForm.format} onChange={event => setProductForm(current => ({ ...current, format: event.target.value }))} placeholder="Course, ebook, program, toolkit…"/></label><label className="wide-field">Audience problem<textarea value={productForm.audienceProblem} onChange={event => setProductForm(current => ({ ...current, audienceProblem: event.target.value }))} placeholder="What specific audience problem does the evidence support?"/></label><label className="wide-field">Buying signal<textarea value={productForm.buyingSignal} onChange={event => setProductForm(current => ({ ...current, buyingSignal: event.target.value }))} placeholder="Comments, questions, requests, or observed demand"/></label><label className="wide-field">Transformation / promise<textarea value={productForm.transformation} onChange={event => setProductForm(current => ({ ...current, transformation: event.target.value }))} placeholder="What practical result should the customer achieve?"/></label><label className="wide-field">Architecture / outline<textarea value={productForm.outline} onChange={event => setProductForm(current => ({ ...current, outline: event.target.value }))} placeholder="Modules, chapters, lessons, tools, sequence, exercises…"/></label><label>Asset requirements<textarea value={productForm.assetRequirements} onChange={event => setProductForm(current => ({ ...current, assetRequirements: event.target.value }))} placeholder="Scripts, worksheets, visuals, templates…"/></label><label>Visual direction<textarea value={productForm.visualDirection} onChange={event => setProductForm(current => ({ ...current, visualDirection: event.target.value }))} placeholder="Higgsfield visual brief and brand direction"/></label><label className="wide-field">Launch notes<textarea value={productForm.launchNotes} onChange={event => setProductForm(current => ({ ...current, launchNotes: event.target.value }))} placeholder="Positioning, launch assumptions, risks, and acceptance criteria"/></label></div><div className="form-actions"><Button variant="outline" onClick={() => setShowProductForm(false)}>Cancel</Button><Button className="primary-button" onClick={submitProduct} disabled={!qualified.length}>Save architecture brief</Button></div></CardContent></Card>}<Card className="workspace-panel"><CardHeader><CardTitle>Product handoff and review</CardTitle><p className="table-subtitle">Each brief stays attached to one creator. No product is approved without a production report and review notes.</p></CardHeader><CardContent>{productBriefs.length ? <div className="product-brief-list">{productBriefs.map(brief => <ProductBriefRow key={brief.id} brief={brief} records={records} onUpdate={onUpdateProductBrief}/>)}</div> : <div className="empty-state small-empty"><div className="empty-icon"><Package size={20}/></div><h3>No product architecture briefs yet</h3><p>Qualify a creator first, then create up to four evidence-led product directions.</p></div>}</CardContent></Card></>}
    {view === "marketing" && <><div className="metrics-grid compact-metrics"><Metric icon={Sparkles} label="Campaign plans" value={String(marketingPlans.length)} detail="creator-specific"/><Metric icon={FileText} label="Calendar items" value={String(marketingItems.length)} detail="pre / launch / post" tone="sage"/><Metric icon={ShieldCheck} label="Approval queue" value={String(marketingPlans.filter(plan => plan.status === "needs_review").length + marketingItems.filter(item => item.status === "needs_review").length)} detail="human review required"/></div><div className="product-toolbar"><div><p className="eyebrow amber-text">Approval before publishing</p><p className="product-guidance">Marketing plans and calendar items stay attached to the approved product and creator. ShadowOS prepares the work; it does not publish externally.</p></div><Button className="primary-button" onClick={() => setShowMarketingForm(value => !value)}><Sparkles size={15}/> {showMarketingForm ? "Close plan form" : "New campaign plan"}</Button></div>{showMarketingForm && <Card className="workspace-panel product-composer"><CardHeader><CardTitle>Create creator-specific campaign plan</CardTitle><p className="table-subtitle">A product must be approved before a marketing plan can be created.</p></CardHeader><CardContent><div className="composer-grid"><label>Creator<select value={marketingForm.creatorId} onChange={event => setMarketingForm(current => ({ ...current, creatorId: event.target.value }))}>{qualified.length ? qualified.map(record => <option key={record.creatorId} value={record.creatorId}>{record.name} · {record.creatorId}</option>) : <option value="">No launch-ready creators</option>}</select></label><label>Approved product<select value={marketingForm.productBriefId ?? ""} onChange={event => setMarketingForm(current => ({ ...current, productBriefId: event.target.value ? Number(event.target.value) : null }))}><option value="">Select product brief</option>{productBriefs.filter(brief => brief.status === "approved").map(brief => <option key={brief.id} value={brief.id}>{brief.productName} · {brief.creatorId}</option>)}</select></label><label>Campaign name<input value={marketingForm.campaignName} onChange={event => setMarketingForm(current => ({ ...current, campaignName: event.target.value }))} placeholder="Launch campaign name"/></label><label>Voice notes<input value={marketingForm.voiceNotes} onChange={event => setMarketingForm(current => ({ ...current, voiceNotes: event.target.value }))} placeholder="Creator voice and boundaries"/></label><label className="wide-field">Audience segment<textarea value={marketingForm.audienceSegment} onChange={event => setMarketingForm(current => ({ ...current, audienceSegment: event.target.value }))} placeholder="Who is this campaign for?"/></label><label className="wide-field">Positioning<textarea value={marketingForm.positioning} onChange={event => setMarketingForm(current => ({ ...current, positioning: event.target.value }))} placeholder="What should the audience understand and believe?"/></label><label className="wide-field">Offer angle<textarea value={marketingForm.offerAngle} onChange={event => setMarketingForm(current => ({ ...current, offerAngle: event.target.value }))} placeholder="Why this product, why now, why this creator?"/></label><label>Pre-launch strategy<textarea value={marketingForm.preLaunchStrategy} onChange={event => setMarketingForm(current => ({ ...current, preLaunchStrategy: event.target.value }))} placeholder="Warm-up, education, demand capture…"/></label><label>Post-launch strategy<textarea value={marketingForm.postLaunchStrategy} onChange={event => setMarketingForm(current => ({ ...current, postLaunchStrategy: event.target.value }))} placeholder="Proof, objections, retention, iteration…"/></label><label className="wide-field">Asset checklist<textarea value={marketingForm.assetChecklist} onChange={event => setMarketingForm(current => ({ ...current, assetChecklist: event.target.value }))} placeholder="Reels, stories, emails, landing page, visuals, testimonials…"/></label></div><div className="form-actions"><Button variant="outline" onClick={() => setShowMarketingForm(false)}>Cancel</Button><Button className="primary-button" onClick={submitMarketingPlan} disabled={!marketingForm.productBriefId}>Save campaign plan</Button></div></CardContent></Card>}<Card className="workspace-panel"><CardHeader><CardTitle>Marketing control room</CardTitle><p className="table-subtitle">Review plans and calendar items before anything is marked ready or published.</p></CardHeader><CardContent>{marketingPlans.length ? <div className="marketing-plan-list">{marketingPlans.map(plan => <div className="marketing-plan-row" key={plan.id}><div className="product-brief-top"><div><span className="eyebrow">{plan.creatorId} · {plan.campaignName}</span><h3>{plan.positioning}</h3><p>{plan.status.replaceAll("_", " ")}</p></div><Badge variant="outline">{plan.status.replaceAll("_", " ")}</Badge></div><div className="marketing-strategy-grid"><div><strong>Pre-launch</strong><p>{plan.preLaunchStrategy}</p></div><div><strong>Post-launch</strong><p>{plan.postLaunchStrategy}</p></div></div><div className="product-row-actions">{plan.status === "draft" && <Button size="sm" variant="outline" onClick={() => onUpdateMarketingPlan({ id: plan.id, status: "needs_review" })}>Submit plan for review</Button>}{plan.status === "needs_review" && <Button size="sm" className="primary-button" onClick={() => onUpdateMarketingPlan({ id: plan.id, status: "approved" })}>Approve plan</Button>}{plan.status === "approved" && <Button size="sm" variant="outline" onClick={() => onUpdateMarketingPlan({ id: plan.id, status: "active" })}>Activate plan</Button>}</div></div>)}</div> : <div className="empty-state small-empty"><div className="empty-icon"><Sparkles size={20}/></div><h3>No campaign plans yet</h3><p>Marketing unlocks after a product is approved in Product Operations.</p></div>}{marketingItems.length > 0 && <div className="marketing-items-list">{marketingItems.map(item => <div className="marketing-item-row" key={item.id}><div><strong>{item.title}</strong><span>{item.phase.replace("_", " ")} · {item.channel} · {item.status}</span><small>{item.objective}</small></div><div>{item.status === "draft" && <Button size="sm" variant="outline" onClick={() => onUpdateMarketingItem({ id: item.id, status: "needs_review" })}>Review item</Button>}{item.status === "needs_review" && <Button size="sm" className="primary-button" onClick={() => onUpdateMarketingItem({ id: item.id, status: "approved" })}>Approve item</Button>}</div></div>)}</div>}</CardContent></Card></>}
    {view === "revenue" && <><div className="metrics-grid compact-metrics"><Metric icon={Wallet} label="Net tracked" value={`$${(revenueTransactions.reduce((sum, tx) => sum + tx.netAmountCents, 0) / 100).toFixed(2)}`} detail="after Whop fees and refunds" tone="sage"/><Metric icon={UserRound} label="Creator share" value={`$${(revenueTransactions.reduce((sum, tx) => sum + tx.creatorShareCents, 0) / 100).toFixed(2)}`} detail="allocated by terms"/><Metric icon={BarChart3} label="ShadowOS share" value={`$${(revenueTransactions.reduce((sum, tx) => sum + tx.shadowShareCents, 0) / 100).toFixed(2)}`} detail="operator revenue" tone="ink"/></div><section className="signal-banner revenue-boundary"><div className="signal-icon"><ShieldCheck size={21}/></div><div><p className="eyebrow amber-text">Read-only Whop boundary</p><p className="signal-copy">The ledger tracks attribution and revenue shares. It does not withdraw, transfer, refund, or move money in Whop.</p></div><Badge variant="outline">{revenueProducts.length ? `${revenueProducts.length} mapped product${revenueProducts.length === 1 ? "" : "s"}` : "No mapped products"}</Badge></section><Card className="workspace-panel"><CardHeader><CardTitle>Whop product mapping</CardTitle><p className="table-subtitle">Map each live product to one creator before importing payments. The connected Whop account currently has no visible business account, so live sync remains pending.</p></CardHeader><CardContent>{revenueProducts.length ? <div className="revenue-product-list">{revenueProducts.map(product => <div className="revenue-product-row" key={product.id}><div><strong>{product.productName}</strong><span>{product.creatorId} · {product.status} · {product.currency}</span></div><Badge variant="outline">{product.whopProductId ?? "Awaiting Whop ID"}</Badge></div>)}</div> : <div className="empty-state small-empty"><div className="empty-icon"><Wallet size={20}/></div><h3>No Whop products mapped yet</h3><p>Once a creator product is live, map its Whop product ID here before recording payments.</p><span className="status-note">Whop connector: connected · visible business accounts: 0</span></div>}</CardContent></Card><Card className="workspace-panel"><CardHeader><CardTitle>Revenue-share terms</CardTitle><p className="table-subtitle">Terms are stored per creator and product. The two shares must total 100% before a transaction can be attributed.</p></CardHeader><CardContent>{revenueTerms.length ? <div className="revenue-term-list">{revenueTerms.map(term => <div className="revenue-term-row" key={term.id}><div><strong>{term.creatorId}</strong><span>Product mapping #{term.whopProductId} · {term.status}</span></div><div className="share-split"><b>{term.creatorSharePercent}% creator</b><b>{term.shadowSharePercent}% ShadowOS</b></div></div>)}</div> : <div className="empty-state small-empty"><div className="empty-icon"><BarChart3 size={20}/></div><h3>No revenue-share terms yet</h3><p>Terms will appear once a product mapping and partnership agreement are approved.</p></div>}</CardContent></Card><Card className="workspace-panel"><CardHeader><CardTitle>Transaction ledger <span className="count-pill">{revenueTransactions.length}</span></CardTitle><p className="table-subtitle">Whop payment imports and manual records remain linked to creator, product, and share terms.</p></CardHeader><CardContent>{revenueTransactions.length ? <div className="transaction-list">{revenueTransactions.map(tx => <div className="transaction-row" key={tx.id}><div><strong>{tx.whopPaymentId ?? `Manual record #${tx.id}`}</strong><span>{tx.creatorId} · {tx.paymentStatus} · {tx.source}</span></div><div><b>${(tx.netAmountCents / 100).toFixed(2)}</b><small>{tx.currency} · creator ${(tx.creatorShareCents / 100).toFixed(2)} · ShadowOS ${(tx.shadowShareCents / 100).toFixed(2)}</small></div></div>)}</div> : <div className="empty-state"><div className="empty-icon"><Wallet size={22}/></div><h3>No transactions imported</h3><p>When a Whop business account is available, the next step is a read-only payment import and attribution review.</p></div>}</CardContent></Card></>}
    {view === "reports" && <><div className="metrics-grid compact-metrics"><Metric icon={UserRound} label="Pipeline size" value={String(records.length)} detail="creator records"/><Metric icon={CircleDashed} label="Screened" value={String(records.filter(record => record.researchStatus !== "unverified").length)} detail="evidence captured" tone="sage"/><Metric icon={Clock3} label="Blockers" value={String(records.filter(record => record.researchStatus === "unverified").length)} detail="awaiting research"/><Metric icon={Database} label="Data source" value={liveLabel === "Supabase live" ? "Live" : "Fallback"} detail={liveLabel} tone="ink"/></div><Card className="workspace-panel"><CardHeader><CardTitle>Operating report</CardTitle><p className="table-subtitle">A current snapshot, intentionally separated from creator-specific evidence.</p></CardHeader><CardContent><div className="report-row"><span>Discovery queue</span><strong>{counts.discovery ?? 0} creators</strong><Badge variant="outline">Research next</Badge></div><div className="report-row"><span>Qualification decisions</span><strong>{qualified.length} creators</strong><Badge variant="outline">No approvals pending</Badge></div><div className="report-row"><span>Outreach activity</span><strong>{drafts.length} drafts</strong><Badge variant="outline">Protected</Badge></div><div className="report-row"><span>Revenue attribution</span><strong>{revenueProducts.length} products</strong><Badge variant="outline">{revenueTransactions.length} payments</Badge></div></CardContent></Card></>}
  </div>;
}

export default function Home() {
  const { theme, toggleTheme } = useTheme();
  const [query, setQuery] = useState("");
  const [selectedId, setSelectedId] = useState("SO-0001");
  const [activeFilter, setActiveFilter] = useState("all");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [activeView, setActiveView] = useState<ViewKey>("overview");
  const [showEvidenceForm, setShowEvidenceForm] = useState(false);
  const [showScreeningForm, setShowScreeningForm] = useState(false);
  const [evidenceTitle, setEvidenceTitle] = useState("");
  const [evidenceSummary, setEvidenceSummary] = useState("");
  const [evidenceUrl, setEvidenceUrl] = useState("");
  const [screening, setScreening] = useState({ audienceFit: 0, buyingSignals: 0, expertiseAuthority: 0, partnershipReadiness: 0, decision: "in_review" as "in_review" | "qualified" | "hold" | "reject", rationale: "" });
  const {
    liveLabel, creatorsQuery, evidenceQuery, screeningQuery, draftsQuery, followupsQuery,
    productBriefsQuery, marketingPlansQuery, marketingItemsQuery, revenueProductsQuery, revenueTermsQuery, revenueTransactionsQuery,
    addEvidenceMutation, saveScreeningMutation, createDraftMutation, draftStatusMutation, scheduleFollowupMutation,
    createProductBriefMutation, updateProductBriefMutation, createMarketingPlanMutation, updateMarketingPlanMutation,
    createMarketingItemMutation, updateMarketingItemMutation,
  } = useDesk(selectedId);
  const navigate = (view: ViewKey) => { setActiveView(view); setSidebarOpen(false); };
  const records = useMemo(() => creatorsQuery.data?.length ? creatorsQuery.data.map(normalizeCreator) : priorityCreators, [creatorsQuery.data]);
  const selected = records.find(c => c.creatorId === selectedId) ?? records[0];

  useEffect(() => { if (records.length && !records.some(c => c.creatorId === selectedId)) setSelectedId(records[0].creatorId); }, [records, selectedId]);

  const counts = useMemo(() => records.reduce<Record<string, number>>((acc, record) => { acc[record.stage] = (acc[record.stage] ?? 0) + 1; return acc; }, {}), [records]);
  const visible = useMemo(() => records.filter(c => { const matchesQuery = `${c.name} ${c.handle} ${c.creatorId}`.toLowerCase().includes(query.toLowerCase()); return matchesQuery && (activeFilter === "all" || c.stage === activeFilter); }), [records, query, activeFilter]);
  const verifiedCount = records.filter(c => c.researchStatus !== "unverified").length;
  const approvalCount = records.filter(c => c.approvalStatus === "needs_review").length;
  const sourceLabel = creatorsQuery.data?.length || liveLabel === "Key missing" || liveLabel === "Supabase error" ? liveLabel : "Local fallback";
  const meta = selected ? (stageMeta[selected.stage] ?? { label: selected.stage, tone: "" }) : stageMeta.discovery;
  const evidence = (evidenceQuery.data ?? []) as EvidenceView[];
  const savedScreening = screeningQuery.data as ScreeningView | null | undefined;
  const openCreator = (creatorId: string) => { setSelectedId(creatorId); setActiveView("overview"); setShowEvidenceForm(false); setShowScreeningForm(false); };
  const createDraft = (input: { creatorId: string; channel: "instagram" | "email"; subject: string | null; body: string; personalizationSummary: string | null }) => createDraftMutation.mutate(input);
  const updateDraftStatus = (id: number, status: "needs_review" | "approved" | "sent" | "replied" | "rejected" | "archived") => draftStatusMutation.mutate({ id, status, note: status === "sent" ? "Marked sent manually after human approval; no connector send was performed." : null });
  const scheduleFollowup = (input: { creatorId: string; draftId: number | null; channel: "instagram" | "email"; dueAt: string; note: string | null }) => scheduleFollowupMutation.mutate(input);
  const createProductBrief = (input: { creatorId: string; hypothesisNumber: number; productName: string; audienceProblem: string; buyingSignal: string | null; transformation: string; format: string; outline: string; assetRequirements: string | null; visualDirection: string | null; launchNotes: string | null }) => createProductBriefMutation.mutate(input);
  const updateProductBrief = (input: { id: number; status?: "architected" | "handed_off" | "in_production" | "submitted_for_review" | "revision_requested" | "approved" | "archived"; productionReport?: string | null; reviewNotes?: string | null }) => updateProductBriefMutation.mutate(input);
  const createMarketingPlan = (input: { creatorId: string; productBriefId: number | null; campaignName: string; audienceSegment: string; positioning: string; offerAngle: string; voiceNotes: string | null; preLaunchStrategy: string; postLaunchStrategy: string; assetChecklist: string | null }) => createMarketingPlanMutation.mutate(input);
  const updateMarketingPlan = (input: { id: number; status: "needs_review" | "approved" | "active" | "paused" | "archived" }) => updateMarketingPlanMutation.mutate(input);
  const createMarketingItem = (input: { creatorId: string; planId: number | null; productBriefId: number | null; phase: "pre_launch" | "launch" | "post_launch"; channel: "instagram" | "email" | "whop" | "community" | "other"; contentType: string; title: string; objective: string; hook: string | null; body: string | null; callToAction: string | null; assetDirection: string | null; scheduledFor: string | null }) => createMarketingItemMutation.mutate(input);
  const updateMarketingItem = (input: { id: number; status: "needs_review" | "approved" | "ready" | "published" | "archived" }) => updateMarketingItemMutation.mutate(input);
  const submitEvidence = () => { if (!selected || !evidenceTitle.trim() || !evidenceSummary.trim()) return; addEvidenceMutation.mutate({ creatorId: selected.creatorId, evidenceType: "note", title: evidenceTitle.trim(), sourceUrl: evidenceUrl.trim(), summary: evidenceSummary.trim(), signal: "unknown", confidence: "medium" }); setEvidenceTitle(""); setEvidenceSummary(""); setEvidenceUrl(""); setShowEvidenceForm(false); };
  const submitScreening = () => { if (!selected) return; saveScreeningMutation.mutate({ creatorId: selected.creatorId, ...screening, rationale: screening.rationale || null, screenedAt: new Date().toISOString() }); setShowScreeningForm(false); };

  return <div className="app-shell">
    <aside className={cn("sidebar", sidebarOpen && "open")}>
      <div className="brand-lockup"><div className="brand-mark">SO</div><div><div className="brand-name">ShadowOS</div><div className="brand-sub">Operating desk</div></div><button className="mobile-close" onClick={() => setSidebarOpen(false)}><X size={16}/></button></div>
      <div className="workspace-chip"><span className="online-dot"/> Control tower <span className="live-label">LIVE</span></div>
      <nav className="side-nav"><div className="nav-label">Workspace</div><button className={cn("nav-item", activeView === "overview" && "active")} onClick={() => navigate("overview")}><Activity size={17}/> Overview <span className="nav-count">{records.length}</span></button><button className={cn("nav-item", activeView === "creators" && "active")} onClick={() => navigate("creators")}><UserRound size={17}/> Creators <span className="nav-count">{records.length}</span></button><button className={cn("nav-item", activeView === "approvals" && "active")} onClick={() => navigate("approvals")}><Target size={17}/> Approvals <span className="nav-count amber">{approvalCount}</span></button><button className={cn("nav-item", activeView === "outreach" && "active")} onClick={() => navigate("outreach")}><Mail size={17}/> Outreach <span className="nav-count">{draftsQuery.data?.length ?? 0}</span></button><div className="nav-label spaced">Operations</div><button className={cn("nav-item", activeView === "products" && "active")} onClick={() => navigate("products")}><Sparkles size={17}/> Products</button><button className={cn("nav-item", activeView === "marketing" && "active")} onClick={() => navigate("marketing")}><Sprout size={17}/> Marketing</button><button className={cn("nav-item", activeView === "revenue" && "active")} onClick={() => navigate("revenue")}><Wallet size={17}/> Whop revenue</button><button className={cn("nav-item", activeView === "reports" && "active")} onClick={() => navigate("reports")}><FileText size={17}/> Reports</button></nav>
      <div className="side-footer"><div className="connector-row"><span className="connector-status connected"/><span>Supabase</span><small>{liveLabel === "Supabase live" ? "live" : liveLabel === "Key missing" ? "key needed" : "ready"}</small></div><div className="connector-row"><span className="connector-status connected"/><span>Whop</span><small>connected</small></div><div className="connector-row"><span className="connector-status connected"/><span>Instagram</span><small>ready</small></div><button className="nav-item theme-toggle" onClick={() => toggleTheme?.()} aria-label="Toggle theme" style={{ marginTop: "8px" }}>{theme === "dark" ? <Sun size={17} /> : <Moon size={17} />}{theme === "dark" ? "Light mode" : "Dark mode"}</button><div className="user-chip"><div className="avatar">RM</div><div><strong>Robert</strong><span>Owner</span></div><MoreHorizontal size={16} className="muted-icon"/></div></div>
    </aside>

    <main className="main-canvas">
      <header className="topbar"><button className="mobile-menu" onClick={() => setSidebarOpen(true)}><Menu size={20}/></button><div><p className="eyebrow">Wednesday · 04 Nov 2026</p><h1>{{"overview":"Control tower","creators":"Creators","approvals":"Approvals","outreach":"Outreach","products":"Products","marketing":"Marketing","revenue":"Whop revenue","reports":"Reports"}[activeView]}</h1></div><div className="top-actions"><div className="search-top"><Search size={16}/><input aria-label="Search creators" placeholder="Search creators, IDs, handles..." value={query} onChange={e => setQuery(e.target.value)}/><kbd>⌘ K</kbd></div><button className="icon-button" aria-label="Notifications"><Bell size={18}/><span className="notification-dot"/></button><Button className="primary-button" onClick={() => navigate("creators")}><Sparkles size={15}/> Open creators</Button></div></header>

      {activeView === "overview" ? <div className="content-wrap">
        <section className="metrics-grid"><Metric icon={UserRound} label="Priority queue" value={String(records.length)} detail="gardening creators"/><Metric icon={CircleDashed} label="Verified" value={String(verifiedCount)} detail="research complete"/><Metric icon={Clock3} label="Awaiting approval" value={String(approvalCount)} detail="human review needed"/><Metric icon={Database} label="System health" value={liveLabel === "Supabase live" ? "Live" : "Ready"} detail={sourceLabel}/></section>

        <div className="section-heading"><div><p className="eyebrow">Priority queue</p><h2>Creator pipeline</h2><p className="section-desc">Review the shortlist, then move each creator through evidence-led screening.</p></div></div>

        <div className="pipeline-strip"><button className={cn("pipeline-cell", activeFilter === "all" && "selected")} onClick={() => setActiveFilter("all")}><span className="pipeline-dot neutral"/>All creators <strong>{records.length}</strong></button><button className={cn("pipeline-cell", activeFilter === "discovery" && "selected")} onClick={() => setActiveFilter("discovery")}><span className="pipeline-dot discovery"/>Discovery <strong>{counts.discovery ?? 0}</strong></button><button className={cn("pipeline-cell", activeFilter === "screening" && "selected")} onClick={() => setActiveFilter("screening")}><span className="pipeline-dot screening"/>Screening <strong>{counts.screening ?? 0}</strong></button><button className={cn("pipeline-cell", activeFilter === "qualified" && "selected")} onClick={() => setActiveFilter("qualified")}><span className="pipeline-dot qualified"/>Qualified <strong>{counts.qualified ?? 0}</strong></button><button className={cn("pipeline-cell", activeFilter === "outreach" && "selected")} onClick={() => setActiveFilter("outreach")}><span className="pipeline-dot outreach"/>Outreach <strong>{counts.outreach ?? 0}</strong></button></div>

        <div className="workspace-grid"><Card className="creator-table-card"><CardHeader className="table-header"><div><CardTitle>Priority creators <span className="count-pill">{visible.length}</span></CardTitle><p className="table-subtitle">{sourceLabel} · source updates remain visible here</p></div><div className="table-tools"><div className="inline-search"><Search size={15}/><input aria-label="Filter creator list" placeholder="Filter list" value={query} onChange={e => setQuery(e.target.value)}/></div><button className="icon-button small" aria-label="More list actions"><MoreHorizontal size={17}/></button></div></CardHeader><CardContent className="table-content"><div className="table-head"><span>Creator</span><span>Niche</span><span>Status</span><span>Score</span><span/></div><ScrollArea className="creator-scroll">{visible.map(c => { const rowMeta = stageMeta[c.stage] ?? { label: c.stage, tone: "" }; return <button key={c.creatorId} className={cn("creator-row", selected?.creatorId === c.creatorId && "selected")} onClick={() => setSelectedId(c.creatorId)}><div className="creator-primary"><div className="creator-avatar">{c.name.split(" ").map(x => x[0]).join("").slice(0,2)}</div><div><strong>{c.name}</strong><span className="handle">@{c.handle}</span></div></div><div className="niche-cell"><span>{c.subNiche ?? "Niche not set"}</span><small>{c.creatorId}</small></div><div><Badge variant="outline" className={cn("status-badge", rowMeta.tone)}>{rowMeta.label}</Badge><small className="status-label">{statusLabel(c)}</small></div><div className="score-cell">{c.qualificationScore || "—"}</div><ArrowUpRight size={15} className="row-arrow"/></button>})}</ScrollArea></CardContent></Card>

          {selected && <Card className="detail-card"><CardHeader className="detail-head"><div className="detail-id"><span className="eyebrow">Creator workspace</span><span className="mono-id">{selected.creatorId}</span></div><button className="icon-button small" aria-label="More creator actions"><MoreHorizontal size={17}/></button></CardHeader><CardContent className="detail-content"><div className="profile-hero"><div className="profile-avatar">{selected.name.split(" ").map(x => x[0]).join("").slice(0,2)}</div><div><h3>{selected.name}</h3><a href={selected.profileUrl} target="_blank" rel="noreferrer">@{selected.handle} <ArrowUpRight size={13}/></a></div></div><div className="detail-tags"><Badge variant="outline" className="status-badge">{selected.industry}</Badge><Badge variant="outline" className={cn("status-badge", meta.tone)}>{meta.label}</Badge><Badge variant="outline" className="status-badge">{statusLabel(selected)}</Badge></div><div className="detail-rule"/><div className="detail-section"><div className="detail-section-title"><ShieldCheck size={15}/> Evidence ledger <span className="section-count">{evidence.length}</span></div><p>{evidence.length ? "Evidence captured for this creator remains attached to this workspace." : "No public evidence has been captured yet. This record is intentionally unverified."}</p>{evidence.slice(0, 3).map(item => <div className="evidence-item" key={item.id}><div><strong>{item.title}</strong><span>{item.summary}</span></div><Badge variant="outline">{item.confidence}</Badge></div>)}{showEvidenceForm && <div className="inline-form"><input aria-label="Evidence title" placeholder="Evidence title" value={evidenceTitle} onChange={event => setEvidenceTitle(event.target.value)}/><input aria-label="Evidence source URL" placeholder="Source URL (optional)" value={evidenceUrl} onChange={event => setEvidenceUrl(event.target.value)}/><textarea aria-label="Evidence summary" placeholder="What did you observe?" value={evidenceSummary} onChange={event => setEvidenceSummary(event.target.value)}/><div className="form-actions"><Button variant="outline" size="sm" onClick={() => setShowEvidenceForm(false)}>Cancel</Button><Button size="sm" className="primary-button" onClick={submitEvidence} disabled={addEvidenceMutation.isPending}>{addEvidenceMutation.isPending ? "Saving…" : "Save evidence"}</Button></div></div>}<Button variant="outline" size="sm" className="full-button" onClick={() => setShowEvidenceForm(value => !value)}><Search size={14}/> {showEvidenceForm ? "Close evidence form" : "Add evidence"}</Button></div><div className="detail-section"><div className="detail-section-title"><Target size={15}/> Qualification screen {savedScreening && <span className="section-count">{savedScreening.audienceFit + savedScreening.buyingSignals + savedScreening.expertiseAuthority + savedScreening.partnershipReadiness}/100</span>}</div><p>{savedScreening?.rationale ?? "Score audience fit, buying signals, authority, and partnership readiness before approval."}</p>{showScreeningForm && <div className="inline-form screening-form">{([["audienceFit","Audience fit"],["buyingSignals","Buying signals"],["expertiseAuthority","Expertise / authority"],["partnershipReadiness","Partnership readiness"]] as const).map(([key, label]) => <label key={key}>{label}<input type="number" min="0" max="25" value={screening[key]} onChange={event => setScreening(current => ({ ...current, [key]: Number(event.target.value) }))}/></label>)}<select aria-label="Screening decision" value={screening.decision} onChange={event => setScreening(current => ({ ...current, decision: event.target.value as typeof current.decision }))}><option value="in_review">Keep in review</option><option value="qualified">Qualify for approval</option><option value="hold">Hold</option><option value="reject">Reject / archive</option></select><textarea aria-label="Screening rationale" placeholder="Decision rationale" value={screening.rationale} onChange={event => setScreening(current => ({ ...current, rationale: event.target.value }))}/><div className="form-actions"><Button variant="outline" size="sm" onClick={() => setShowScreeningForm(false)}>Cancel</Button><Button size="sm" className="primary-button" onClick={submitScreening} disabled={saveScreeningMutation.isPending}>{saveScreeningMutation.isPending ? "Saving…" : "Save screening"}</Button></div></div>}<Button variant="outline" size="sm" className="full-button" onClick={() => setShowScreeningForm(value => !value)}><Target size={14}/> {showScreeningForm ? "Close screening form" : "Open screening form"}</Button></div><div className="detail-section"><div className="detail-section-title"><Target size={15}/> Next action</div><div className="next-action"><div className="action-icon"><Sprout size={16}/></div><div><strong>{selected.researchStatus === "unverified" ? "Begin profile screening" : "Review qualification"}</strong><span>{selected.researchStatus === "unverified" ? "Verify account, niche, activity, and initial audience signals." : "Review the evidence and decide whether this creator can move forward."}</span></div></div></div><div className="detail-section"><div className="detail-section-title"><FileText size={15}/> Workspace folders</div><div className="folder-row"><span>01 · Creator intelligence</span><span>—</span></div><div className="folder-row"><span>02 · Audience evidence</span><span>—</span></div><div className="folder-row"><span>03 · Product strategy</span><span>—</span></div><div className="folder-row"><span>04 · Outreach</span><span>—</span></div></div><div className="detail-section muted-panel"><div className="detail-section-title"><Instagram size={15}/> Channel readiness</div><div className="channel-row"><span><Instagram size={14}/> Instagram</span><Badge variant="outline">Manual DM capture</Badge></div><div className="channel-row"><span><Mail size={14}/> Email</span><Badge variant="outline">Not drafted</Badge></div></div></CardContent><div className="detail-footer"><Button className="primary-button full-button" onClick={() => setShowScreeningForm(true)}><Sprout size={15}/> Start screening</Button></div></Card>}
        </div>
      </div> : <WorkspaceView view={activeView as Exclude<ViewKey, "overview">} records={records} counts={counts} liveLabel={sourceLabel} drafts={(draftsQuery.data ?? []) as DraftView[]} followups={(followupsQuery.data ?? []) as FollowupView[]} productBriefs={(productBriefsQuery.data ?? []) as ProductBriefView[]} marketingPlans={(marketingPlansQuery.data ?? []) as MarketingPlanView[]} marketingItems={(marketingItemsQuery.data ?? []) as MarketingItemView[]} revenueProducts={(revenueProductsQuery.data ?? []) as RevenueProductView[]} revenueTerms={(revenueTermsQuery.data ?? []) as RevenueTermView[]} revenueTransactions={(revenueTransactionsQuery.data ?? []) as RevenueTransactionView[]} onDraftStatus={updateDraftStatus} onCreateDraft={createDraft} onScheduleFollowup={scheduleFollowup} onCreateProductBrief={createProductBrief} onUpdateProductBrief={updateProductBrief} onCreateMarketingPlan={createMarketingPlan} onUpdateMarketingPlan={updateMarketingPlan} onCreateMarketingItem={createMarketingItem} onUpdateMarketingItem={updateMarketingItem} onOpenCreator={openCreator} />}
    </main>
  </div>;
}
